var LS_HIST="hcm_typing_history_v1", LS_DONE="hcm_drills_done_v1";
function newClientId(){ return "r"+Date.now().toString(36)+Math.random().toString(36).slice(2,9); }
function loadHist(){ try{var h=JSON.parse(localStorage.getItem(LS_HIST))||[]; h.forEach(function(x){ if(!x.clientId) x.clientId=newClientId(); if(!x.ts){ var t=Date.parse(x.d); x.ts=isNaN(t)?new Date().toISOString():new Date(t).toISOString(); } }); return h;}catch(e){return[]} }
function saveHist(h){ try{localStorage.setItem(LS_HIST,JSON.stringify(h.slice(0,200)))}catch(e){} }
function loadDone(){ try{return JSON.parse(localStorage.getItem(LS_DONE))||{}}catch(e){return{}} }
function saveDone(d){ try{localStorage.setItem(LS_DONE,JSON.stringify(d))}catch(e){} }
var LS_BEST="hcm_lesson_best10_v1";
var CLOUD_BEST_COL="lessons";
function loadBest(){ try{var b=JSON.parse(localStorage.getItem(LS_BEST))||{}; return (b&&typeof b==="object"&&!Array.isArray(b))?b:{};}catch(e){return{}} }
function saveBest(b){ try{localStorage.setItem(LS_BEST,JSON.stringify(b||{}))}catch(e){} }
function entryTs(en){ var t=Date.parse((en&&(en.ts||en.d))||""); return isNaN(t)?0:t; }

function sortBestArr(arr){
  return (arr||[]).map(function(en,i){ return {en:en,i:i}; }).sort(function(a,b){
    var dt=entryTs(b.en)-entryTs(a.en);
    if(dt!==0) return dt;
    return b.i-a.i;
  }).map(function(x){ return x.en; });
}
function pushBest(id,entry){
  if(!id||!entry) return [];
  var map=loadBest(); var arr=Array.isArray(map[id])?map[id]:[];
  arr.push(entry); arr=sortBestArr(arr).slice(0,10); map[id]=arr; saveBest(map); return arr;
}
function lessonStatus(id){
  var bestMap=loadBest(); var arr=Array.isArray(bestMap[id])?bestMap[id]:[];
  var doneMap={}; try{doneMap=loadDone();}catch(e){}
  var passed=!!doneMap[id];

  var best=null;
  arr.forEach(function(en){
    if(!en) return;
    if(!best || (en.net||0)>(best.net||0) ||
      ((en.net||0)===(best.net||0) && ((en.acc||0)>(best.acc||0) ||
      ((en.acc||0)===(best.acc||0) && entryTs(en)>=entryTs(best))))) best=en;
  });
  return {attempts:arr.length,best:best,passed:passed,completed:(arr.length>0||passed)};
}

function durSummaryHtml(id){
  var map=loadBest(); var arr=Array.isArray(map[id])?map[id]:[];
  if(!arr.length) return "";
  var done={}; arr.forEach(function(en){ if(en && en.min) done[en.min]=true; });
  var parts=[1,2,5,10,15].map(function(d){
    return done[d] ? "<span style='color:var(--green);font-weight:800'>"+d+" min ✓</span>"
                   : "<span style='color:var(--muted)'>"+d+" min ·</span>";
  });
  return "<span class='bestLine'>Completed at: "+parts.join(" ")+"</span>";
}
function statusHtml(id){
  var st=lessonStatus(id); var h="";
  if(st.completed) h+="<span class='doneState doneYes'>✓ Completed</span>";
  else h+="<span class='doneState'>· Not attempted yet</span>";
  if(st.passed) h+="<span class='done'>✅ Passed — 98%+ accuracy</span>";
  if(st.best) h+="<span class='bestLine'>Best: "+st.best.net+" WPM · "+(+st.best.acc).toFixed(1)+"% · "+st.best.errs+" errors · "+(st.best.net>=30?st.best.marks+" / 25":"DQ")+"</span>";
  if(st.attempts>0) h+="<span class='bestLine'>Attempts recorded: "+st.attempts+" / 10</span>";
  h+=durSummaryHtml(id);
  return h;
}
function saveBestToCloud(lessonId){
  try{
    if(typeof fbDb==="undefined"||!fbDb||!window.__fbUser||!lessonId) return Promise.resolve(false);
    if(rateLimited("cloudWrite")) return Promise.resolve(false);
    var map=loadBest(); var arr=Array.isArray(map[lessonId])?sortBestArr(map[lessonId]).slice(0,10):[];
    return fbDb.collection("users").doc(window.__fbUser.uid).collection(CLOUD_BEST_COL).doc(lessonId).set({entries:arr},{merge:true}).then(function(){return true;}).catch(function(e){console.warn("Cloud best save failed",e);return false;});
  }catch(e){console.warn("Cloud best save failed",e);return Promise.resolve(false);}
}
function mergeBestFromCloud(){
  try{
    if(typeof fbDb==="undefined"||!fbDb||!window.__fbUser) return Promise.resolve(false);
    var uid=window.__fbUser.uid;
    return fbDb.collection("users").doc(uid).collection(CLOUD_BEST_COL).get().then(function(snap){
      var local=loadBest(); var changed=false; var uploads=[];
      var cloudIds={};
      snap.forEach(function(doc){
        cloudIds[doc.id]=true;
        var v=doc.data()||{}; var carr=Array.isArray(v.entries)?v.entries:[];
        var larr=Array.isArray(local[doc.id])?local[doc.id]:[];
        var seen={}, merged=[];
        carr.concat(larr).forEach(function(en){
          if(!en) return;
          var key=[en.ts||en.d||"",en.gross||0,en.net||0,en.acc||0,en.errs||0].join("|");
          if(seen[key]) return; seen[key]=1; merged.push(en);
        });
        merged=sortBestArr(merged).slice(0,10);
        if(JSON.stringify(merged)!==JSON.stringify(larr)){ local[doc.id]=merged; changed=true; }
        if(JSON.stringify(merged)!==JSON.stringify(carr)) uploads.push(doc.id);
      });
      Object.keys(local).forEach(function(id){ if(!cloudIds[id]) uploads.push(id); });
      if(changed) saveBest(local);
      if(typeof renderDrills==="function") renderDrills();
      if(typeof renderWarmups==="function") renderWarmups();
      if(typeof updateLessonHistory==="function") updateLessonHistory();
      var ups=uploads.map(function(id){ return saveBestToCloud(id); });
      return Promise.all(ups).then(function(){return true;});
    }).catch(function(e){console.warn("Cloud best merge failed",e);return false;});
  }catch(e){console.warn("Cloud best merge failed",e);return Promise.resolve(false);}
}
function clearBestFromCloud(){
  try{
    if(typeof fbDb==="undefined"||!fbDb||!window.__fbUser) return;
    var uid=window.__fbUser.uid;
    fbDb.collection("users").doc(uid).collection(CLOUD_BEST_COL).get().then(function(snap){
      snap.forEach(function(doc){ doc.ref.delete().catch(function(e){console.warn("Cloud best delete failed",e);}); });
    }).catch(function(e){console.warn("Cloud best clear failed",e);});
  }catch(e){console.warn("Cloud best clear failed",e);}
}

function marksFor(net){
  if(net<30) return 0; if(net<31) return 10; if(net<=35) return 12; if(net<=40) return 15;
  if(net<=45) return 18; if(net<=50) return 21; return 25;
}
function fmtTime(s){ s=Math.max(0,Math.ceil(s)); return Math.floor(s/60)+":"+("0"+(s%60)).slice(-2); }

var state={ target:"", typed:[], caret:0, started:false, startT:0, durMin:5, timer:null, finished:false,
  errCat:{spelling:0,capital:0,punct:0,spacing:0,other:0}, errKeys:{}, errWords:{},
  currentId:"paraM1", currentName:"Paragraph — Medium 1 · Public Administration", isDrill:false,
  examMode:false, paperView:false, bsCount:0, lastMistakes:[] };

