var spanCache=[];
var spanText=[];
function buildSpans(){
  var t=state.target, html="";
  for(var i=0;i<t.length;i++){ html+='<span class="ch">'+escapeHtml(t[i])+'</span>'; }
  typeText.innerHTML=html;
  spanCache=new Array(t.length);
  spanText=new Array(t.length);
  for(var j=0;j<t.length;j++){ spanCache[j]="ch"; spanText[j]=t[j]; }
}
function renderText(){
  var t=state.target, pos=state.typed.length;
  var cpos=Math.max(0,Math.min(state.caret||0, pos));
  var raw=!highlightOn();
  typeText.classList.toggle("raw", raw);
  if(typeText.children.length!==t.length) buildSpans();
  for(var i=0;i<t.length;i++){
    var cls="ch";

    var glyph = i<pos ? state.typed[i].ch : t[i];
    if(spanText[i]!==glyph){ spanText[i]=glyph; typeText.children[i].textContent=glyph; }
    if(i<pos){

      if(raw) cls += " typed";
      else cls += state.typed[i].ok ? " ok typed" : (glyph===" " ? " bad spaceBad typed" : " bad typed");
    }
    else if(i===pos){ cls += " cur"; }
    if(spanCache[i]!==cls){ spanCache[i]=cls; typeText.children[i].className=cls; }
  }
  scrollCursorIntoView(cpos);
  positionCaret(cpos);
  syncPaperScroll();
  if(typeof updateNumHint==="function") updateNumHint();
}
function scrollCursorIntoView(pos){
  var kids=typeText.children, total=kids.length;
  if(!total) return;

  var idx=Math.min(Math.max(pos,0), total-1);
  var cur=kids[idx];
  if(!cur) return;

  var savedWinY=window.scrollY, savedWinX=window.scrollX;
  var boxRect=typeBox.getBoundingClientRect();
  var curRect=cur.getBoundingClientRect();
  if((curRect.height===0||curRect.width===0) && idx>0){

    var prevRect=kids[idx-1].getBoundingClientRect();
    if(prevRect.height>0) curRect=prevRect;
  }
  var lh=parseFloat(window.getComputedStyle(typeText).lineHeight);
  if(isNaN(lh)||lh<=0) lh=curRect.height>0?curRect.height:42;
  var borderTop=typeBox.clientTop||0;
  var lineTop=curRect.top-boxRect.top+typeBox.scrollTop;
  var lineBottom=lineTop+lh;
  var viewH=typeBox.clientHeight;
  var viewTop=typeBox.scrollTop+borderTop, viewBottom=viewTop+viewH;
  var desired=typeBox.scrollTop;

  if(lineBottom+lh>viewBottom){ desired=lineBottom+lh-borderTop-viewH; }
  if(lineTop-lh<desired+borderTop){ desired=lineTop-lh-borderTop; }

  var maxScroll=Math.max(0, typeBox.scrollHeight-typeBox.clientHeight);
  if(desired>maxScroll) desired=maxScroll;
  if(desired<0) desired=0;
  if(desired!==typeBox.scrollTop) typeBox.scrollTop=desired;
  if(window.scrollY!==savedWinY||window.scrollX!==savedWinX) window.scrollTo(savedWinX,savedWinY);
}

var caretBlinkKey="";
function caretOffsetInBox(node){
  var x=0, y=0, n=node;
  while(n && n!==typeBox){ x+=(n.offsetLeft||0); y+=(n.offsetTop||0); n=n.offsetParent; }
  return {x:x, y:y};
}
function positionCaret(pos){
  var el=document.getElementById("caretEl"); if(!el) return;
  var kids=typeText.children, total=kids.length;
  if(!total){ el.classList.remove("on"); return; }
  var lh=parseFloat(window.getComputedStyle(typeText).lineHeight);
  if(isNaN(lh)||lh<=0) lh=42;
  var x, y;
  if(pos<total){
    var span=kids[pos], off=caretOffsetInBox(span);
    if((span.offsetWidth===0||span.offsetHeight===0)&&pos>0){
      var prev=kids[pos-1], poff=caretOffsetInBox(prev);
      x=poff.x+(prev.offsetWidth||0); y=poff.y;
    } else { x=off.x; y=off.y; }
  } else {
    var last=kids[total-1], loff=caretOffsetInBox(last);
    x=loff.x+(last.offsetWidth||0); y=loff.y;
  }

  el.style.left=(x-1)+"px";
  el.style.top=(y+lh*0.14)+"px";
  el.style.height=(lh*0.72)+"px";
  el.classList.add("on");

  var key=pos+"|"+x+"|"+y;
  if(key!==caretBlinkKey){
    caretBlinkKey=key;
    el.style.animation="none";
    void el.offsetWidth;
    el.style.animation="";
  }
}

function syncPaperScroll(){
  if(!state.paperView) return;
  var sh=document.getElementById("paperSheet"); if(!sh) return;
  var max=sh.scrollHeight-sh.clientHeight; if(max<=0) return;
  var prog=state.target.length? state.typed.length/state.target.length : 0;
  var target=Math.round(prog*max);
  if(paperHold){ if(Math.abs(sh.scrollTop-target)<=48) paperHold=false; else return; }
  if(Math.abs(sh.scrollTop-target)<2) return;
  paperProgScroll=true; sh.scrollTop=target;
  requestAnimationFrame(function(){ paperProgScroll=false; });
}
function focusCapture(){
  try{ capture.focus({preventScroll:true}); }catch(e){ capture.focus(); }
}
function escapeHtml(s){ return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }

function cmpComparisonHtml(eTokens,gTokens,eStat,gStat,counts,halfCatsApply){
  counts=counts||{};
  var hw=halfCatsApply? "Half":"Full";
  var key=[["spelling","Spelling","Full"],["skipped","Skipped","Full"],["extra","Extra","Full"],["capital","Capitalisation",hw],["punct","Punctuation",hw],["spacing","Spacing",hw]];
  var chips=key.map(function(k){
    return "<span class='cmpKey'><span class='cmpDot cw-"+k[0]+"'></span>"+k[1]+" ("+k[2]+")"+(counts[k[0]]!=null?" · "+counts[k[0]]:"")+"</span>";
  }).join("");
  function panel(tokens,stat){
    return tokens.map(function(w,idx){
      var s=stat&&stat[idx];
      if(!s||s.st==="ok") return escapeHtml(w);
      return "<span class='cw-"+s.cat+"'>"+escapeHtml(w)+"</span>";
    }).join(" ");
  }
  return "<div class='cmpKeys'>"+chips+"</div><div class='cmpGrid'>"
    +"<div class='cmpPanel'><h4>Original Passage</h4><p>"+panel(eTokens,eStat)+"</p></div>"
    +"<div class='cmpPanel'><h4>Your Typed Passage</h4><p>"+(gTokens.length? panel(gTokens,gStat) : "(nothing typed)")+"</p></div></div>";
}
function ringTileHtml(valueText,label,pct,color){
  pct=Math.max(0,Math.min(100,+pct||0));
  return "<div class='ringStat'><div class='ringWrap'><svg width='76' height='76' viewBox='0 0 76 76' aria-hidden='true'><circle class='ringBg' cx='38' cy='38' r='32' stroke-width='7' fill='none'/><circle class='ringFg' cx='38' cy='38' r='32' stroke-width='7' fill='none' stroke='"+color+"' stroke-linecap='round' stroke-dasharray='201.06' stroke-dashoffset='201.06' data-pct='"+pct+"'/></svg><div class='ringVal'>"+valueText+"</div></div><div class='l'>"+label+"</div></div>";
}
function animateRings(root){
  if(!root) return;
  var fgs=root.querySelectorAll(".ringFg"); if(!fgs.length) return;
  requestAnimationFrame(function(){ requestAnimationFrame(function(){
    fgs.forEach(function(c){
      var pct=parseFloat(c.getAttribute("data-pct")||"0")||0;
      pct=Math.max(0,Math.min(100,pct));
      c.style.strokeDashoffset=String(201.06*(1-pct/100));
    });
  }); });
}

function classify(exp,got){
  if(exp===" "||got===" ") return "spacing";
  if(/[.,;:!?'"()\/\-]/.test(exp)||/[.,;:!?'"()\/\-]/.test(got)) return "punct";
  if(exp.toLowerCase()===got.toLowerCase() && exp!==got) return "capital";
  if(/[A-Z]/.test(exp)&&/[a-z]/.test(got)&&exp.toLowerCase()!==got.toLowerCase()) return "spelling";
  if(/[A-Z]/.test(exp)||/[A-Z]/.test(got)) return "capital";
  return "spelling";
}
function currentWord(pos){
  var t=state.target, s=pos; while(s>0 && t[s-1]!==" ") s--;
  var e=pos; while(e<t.length && t[e]!==" ") e++;
  return t.slice(s,e);
}
function startTimer(){
  state.started=true; state.startT=Date.now();
  document.body.classList.add("focused");
  var fsT0=document.getElementById("fsTime"); if(fsT0) fsT0.textContent=fmtTime(state.durMin*60);
  if(typeof paintSubmitBtn==="function") paintSubmitBtn();
  var eb0=document.getElementById("endTestBtn"); if(eb0 && state.examMode) eb0.disabled=false;
  var et0=document.getElementById("examToggle"); if(et0 && state.examMode) et0.disabled=true;
  state.timer=setInterval(function(){
    var el=(Date.now()-state.startT)/1000, total=state.durMin*60;
    document.getElementById("sTime").textContent=fmtTime(total-el);
    var fsT=document.getElementById("fsTime"); if(fsT) fsT.textContent=fmtTime(total-el);
    document.getElementById("progBar").style.width=Math.min(100,el/total*100)+"%";
    updateStats(el);
    if(el>=total) finishTest();
  },200);
}

function hcmWordTokens(str){
  var out=[], m, re=/\S+/g;
  while((m=re.exec(str||""))!==null) out.push({w:m[0], s:m.index, e:m.index+m[0].length});
  return out;
}
function alignWordsHcm(target, typedStr){
  var T=hcmWordTokens(target), G=hcmWordTokens(typedStr);
  var n=T.length, m=G.length, i, j;
  var Tw=[], Gw=[];
  for(i=0;i<n;i++) Tw.push(T[i].w);
  for(j=0;j<m;j++) Gw.push(G[j].w);
  function posMatches(a,b){ var c=0, lim=Math.min(a.length,b.length); for(var q=0;q<lim;q++){ if(a[q]===b[q]) c++; } return c; }
  function prefixLen(a,b){ var c=0, lim=Math.min(a.length,b.length); while(c<lim&&a[c]===b[c]) c++; return c; }

  var tIdx={}, gIdx={}, tUniq=[], gUniq=[], tSeq=new Int32Array(n), gSeq=new Int32Array(m);
  for(i=0;i<n;i++){ var w1=Tw[i]; if(tIdx[w1]===undefined){ tIdx[w1]=tUniq.length; tUniq.push(w1); } tSeq[i]=tIdx[w1]; }
  for(j=0;j<m;j++){ var w2=Gw[j]; if(gIdx[w2]===undefined){ gIdx[w2]=gUniq.length; gUniq.push(w2); } gSeq[j]=gIdx[w2]; }
  var gu=gUniq.length, C=new Float64Array(tUniq.length*gu);
  for(i=0;i<tUniq.length;i++) for(j=0;j<gu;j++){
    C[i*gu+j]= tUniq[i]===gUniq[j]? 0 : 1 - 0.01*(prefixLen(tUniq[i],gUniq[j])/Math.max(tUniq[i].length,gUniq[j].length));
  }
  var Wd=m+1, D=new Float64Array((n+1)*Wd);
  for(i=0;i<=n;i++) D[i*Wd]=i;
  for(j=0;j<=m;j++) D[j]=j;
  for(i=1;i<=n;i++){
    var ri=i*Wd, rp=(i-1)*Wd, crow=tSeq[i-1]*gu;
    for(j=1;j<=m;j++){
      var a=D[rp+j-1]+C[crow+gSeq[j-1]], b=D[rp+j]+1, c=D[ri+j-1]+1;
      D[ri+j]= a<b? (a<c? a:c) : (b<c? b:c);
    }
  }

  var kStar=0; for(i=1;i<=n;i++){ if(D[i*Wd+m]<D[kStar*Wd+m]-1e-9) kStar=i; }
  var pairs=[]; i=kStar; j=m;
  while(i>0||j>0){
    if(i>0&&j>0&&Math.abs(D[i*Wd+j]-(D[(i-1)*Wd+j-1]+C[tSeq[i-1]*gu+gSeq[j-1]]))<1e-9){
      pairs.push({kind:(Tw[i-1]===Gw[j-1]?"ok":"sub"), exp:Tw[i-1], got:Gw[j-1], ti:i-1, gi:j-1});
      i--; j--;
    } else if(i>0&&(j===0||Math.abs(D[i*Wd+j]-(D[(i-1)*Wd+j]+1))<1e-9)){
      pairs.push({kind:"del", exp:Tw[i-1], got:"", ti:i-1, gi:-1});
      i--;
    } else if(j>0){
      pairs.push({kind:"ins", exp:"", got:Gw[j-1], ti:-1, gi:j-1});
      j--;
    } else break;
  }
  pairs.reverse();

  var lastPaired=-1;
  pairs.forEach(function(p){ if(p.gi>=0&&p.ti>lastPaired) lastPaired=p.ti; });
  var mistakes=0, incorrectChars=0, kept=[], spanWords=0;
  T.forEach(function(tk){ if(tk.s<(typedStr||"").length) spanWords++; });
  pairs.forEach(function(p){
    if(p.kind==="del"&&p.ti>lastPaired) return;
    if(p.kind==="sub"&&p.gi===m-1&&p.got.length<p.exp.length&&p.exp.indexOf(p.got)===0){
      p={kind:"ok", exp:p.exp, got:p.got, ti:p.ti, gi:p.gi};
    }
    if(p.kind==="sub"){ mistakes++; incorrectChars+=p.got.length-posMatches(p.exp,p.got); }
    else if(p.kind==="del"){ mistakes++; }
    else if(p.kind==="ins"){ mistakes++; incorrectChars+=p.got.length; }
    kept.push(p);
  });

  var collapsed=[], ci2=0, didCollapse=false;
  while(ci2<kept.length){
    var a=kept[ci2], b=kept[ci2+1];
    if(b){
      if((a.kind==="sub"&&b.kind==="del"&&a.exp+b.exp===a.got)||(a.kind==="del"&&b.kind==="sub"&&a.exp+b.exp===b.got)){
        var subP=(a.kind==="sub")? a:b;
        collapsed.push({kind:"spacing", exp:a.exp+" "+b.exp, got:subP.got, ti:a.ti, gi:subP.gi});
        ci2+=2; didCollapse=true; continue;
      }
      if((a.kind==="sub"&&b.kind==="ins"&&a.exp===a.got+b.got)||(a.kind==="ins"&&b.kind==="sub"&&b.exp===a.got+b.got)){
        var subQ=(a.kind==="sub")? a:b;
        collapsed.push({kind:"spacing", exp:subQ.exp, got:a.got+" "+b.got, ti:subQ.ti, gi:a.gi});
        ci2+=2; didCollapse=true; continue;
      }
    }
    collapsed.push(a); ci2++;
  }
  if(didCollapse){
    kept=collapsed; mistakes=0; incorrectChars=0;
    kept.forEach(function(p){
      if(p.kind==="sub"){ mistakes++; incorrectChars+=p.got.length-posMatches(p.exp,p.got); }
      else if(p.kind==="del"){ mistakes++; }
      else if(p.kind==="ins"){ mistakes++; incorrectChars+=p.got.length; }
      else if(p.kind==="spacing"){ mistakes++; incorrectChars+=p.got.length; }
    });
  }
  var typedChars=(typedStr||"").length;
  return {pairs:kept, mistakes:mistakes, correctChars:typedChars-incorrectChars,
          wordsTyped:m, spanWords:spanWords, typedChars:typedChars};
}

function displayFlagsHcm(target, typedStr){
  var flags=[], q;
  for(q=0;q<typedStr.length;q++) flags.push(true);
  var al=alignWordsHcm(target, typedStr);
  var G=hcmWordTokens(typedStr);
  var byGi={};
  al.pairs.forEach(function(p){ if(p.gi>=0) byGi[p.gi]=p; });
  G.forEach(function(tk, gi){
    var p=byGi[gi], c;
    if(!p) return;
    if(p.kind==="ins"){ for(c=tk.s;c<tk.e;c++) flags[c]=false; return; }
    if(p.kind!=="ok"&&p.kind!=="sub") return;
    for(c=tk.s;c<tk.e;c++){
      var rel=c-tk.s;
      flags[c]= rel<p.exp.length && p.exp.charAt(rel)===tk.w.charAt(rel);
    }
  });
  return flags;
}
function typedString(){ var v=""; state.typed.forEach(function(x){ v+=x.ch; }); return v; }
function stats(el){
  var typedStr=typedString(), pos=typedStr.length;
  var al=alignWordsHcm(state.target,typedStr);
  var mins=Math.max(el,1)/60;
  var W5=Math.round(pos/5);
  var gross=W5/mins;
  var net=Math.max(0,(W5 - 10*al.mistakes)/mins);
  var acc=W5? Math.max(0,Math.min(100,(W5 - al.mistakes)/W5*100)):100;
  var accChar=pos? (al.correctChars/pos*100):100;
  var words=W5;
  return {pos:pos,errs:al.mistakes,gross:gross,net:net,acc:acc,accChar:accChar,words:words};
}
function updateStats(el){
  var s=stats(el|| (state.started?(Date.now()-state.startT)/1000:0));
  document.getElementById("sGross").textContent=Math.round(s.gross);
  document.getElementById("sNet").textContent=Math.round(s.net);
  document.getElementById("sAcc").textContent=s.acc.toFixed(1)+"%";
  document.getElementById("sErr").textContent=s.errs;
  document.getElementById("sWords").textContent=s.words;
  document.getElementById("sChars").textContent=s.pos;
  var m=document.getElementById("sMarks");
  if(!state.started||s.pos<10){ m.textContent="—"; }
  else { var mk=marksFor(s.net); m.textContent = s.net<30 ? "0 · DQ" : mk+" / 25"; }
}

var pendingWinY=null, pendingWinX=null;
capture.addEventListener("input",function(){
  if(state.finished) return;
  var wy=(pendingWinY!=null?pendingWinY:window.scrollY), wx=(pendingWinX!=null?pendingWinX:window.scrollX);
  var v=capture.value;
  if(window.TEL) TEL.feed(v);
  if(!state.started && v.length>0) startTimer();

  if(v.length>state.target.length){
    var csCap=capture.selectionStart;
    v=v.slice(0,state.target.length);
    capture.value=v;
    var csNew=Math.max(0,Math.min(csCap!=null?csCap:v.length, v.length));
    try{ capture.setSelectionRange(csNew,csNew); }catch(e){}
  }

  var prevLen=state.typed.length;

  state.errCat={spelling:0,capital:0,punct:0,spacing:0,other:0}; state.errKeys={}; state.errWords={};
  state.typed=[];
  for(var i=0;i<v.length && i<state.target.length;i++){
    var exp=state.target[i], got=v[i], ok=exp===got;
    state.typed.push({ch:got,ok:ok});
    if(!ok){
      state.errCat[classify(exp,got)]++;
      state.errKeys[exp]=(state.errKeys[exp]||0)+1;
      var w=currentWord(i); if(w) state.errWords[w]=(state.errWords[w]||0)+1;
    }
  }

  var dfl=displayFlagsHcm(state.target, v.slice(0,state.typed.length));
  for(var di=0;di<state.typed.length;di++){ state.typed[di].ok=!!dfl[di]; }

  var selNow=capture.selectionStart;
  state.caret=Math.max(0,Math.min(selNow!=null?selNow:state.typed.length, state.typed.length));

  renderText(); updateStats(state.started?(Date.now()-state.startT)/1000:0);

  requestAnimationFrame(function(){
    if(window.scrollY!==wy||window.scrollX!==wx) window.scrollTo(wx,wy);

    scrollCursorIntoView(state.caret);
    pendingWinY=null; pendingWinX=null;
  });
  var mhEl=document.getElementById("modeHint");
  if(state.typed.length>=state.target.length){

    if(mhEl) mhEl.textContent= state.examMode
      ? "Text complete — timer still running. You can still correct anything; press End Test when ready."
      : "Text complete — timer still running. You can still correct anything; press Submit when ready.";
  } else if(mhEl && mhEl.textContent.indexOf("Text complete")===0){
    mhEl.textContent= state.examMode? "Real exam mode · "+state.currentName+" · "+state.durMin+" min · stats hidden until the end" : "";
  }
  if(typeof paintSubmitBtn==="function") paintSubmitBtn();
});
function setHcmCaret(c){
  c=Math.max(0,Math.min(c, state.typed.length));
  state.caret=c;
  try{ capture.setSelectionRange(c,c); }catch(e){}
  renderText();
}
function syncHcmCaret(){
  if(state.finished) return;
  var cs=capture.selectionStart; if(cs==null) return;
  cs=Math.max(0,Math.min(cs, state.typed.length));
  if(cs!==state.caret){ state.caret=cs; renderText(); }
}
function hcmLineCaret(dir){
  var kids=typeText.children, total=kids.length;
  if(!total) return state.caret;
  var c=Math.max(0,Math.min(state.caret||0, state.typed.length));
  var anchorIdx=Math.min(c, total-1);
  var anchor=kids[anchorIdx];
  var aTop=anchor.offsetTop;
  var aLeft= c<total? anchor.offsetLeft : anchor.offsetLeft+anchor.offsetWidth;
  var rowTops=[];
  for(var i=0;i<total;i++){ if(rowTops.indexOf(kids[i].offsetTop)<0) rowTops.push(kids[i].offsetTop); }
  rowTops.sort(function(a,b){ return a-b; });
  if(dir==="home"||dir==="end"){
    var first=-1, last=-1;
    for(var j=0;j<total;j++){ if(kids[j].offsetTop===aTop){ if(first<0) first=j; last=j; } }
    if(first<0) return c;
    return dir==="home"? Math.min(first, state.typed.length) : Math.min(last+1, state.typed.length);
  }
  var targetTop=null, ri;
  if(dir==="up"){ for(ri=rowTops.length-1;ri>=0;ri--){ if(rowTops[ri]<aTop){ targetTop=rowTops[ri]; break; } } }
  else { for(ri=0;ri<rowTops.length;ri++){ if(rowTops[ri]>aTop){ targetTop=rowTops[ri]; break; } } }
  if(targetTop==null) return c;
  var best=-1, bestD=Infinity;
  for(var k=0;k<total;k++){
    if(kids[k].offsetTop!==targetTop) continue;
    var d=Math.abs(kids[k].offsetLeft-aLeft);
    if(d<bestD){ bestD=d; best=k; }
  }
  if(best<0) return c;
  var lastSpan=kids[best];
  var nc= (aLeft>lastSpan.offsetLeft+lastSpan.offsetWidth)? best+1 : best;
  return Math.max(0,Math.min(nc, state.typed.length));
}
capture.addEventListener("keydown",function(e){
  pendingWinY=window.scrollY; pendingWinX=window.scrollX;

  if(e.key==="Backspace" && !state.finished) state.bsCount++;
  if(state.finished) return;
  if(e.key==="ArrowUp"||e.key==="ArrowDown"||e.key==="Home"||e.key==="End"){
    e.preventDefault();
    setHcmCaret(hcmLineCaret(e.key==="ArrowUp"?"up":e.key==="ArrowDown"?"down":e.key==="Home"?"home":"end"));
  }
});
capture.addEventListener("keyup",function(e){
  if(e.key==="ArrowLeft"||e.key==="ArrowRight") syncHcmCaret();
});
capture.addEventListener("select",function(){ syncHcmCaret(); });
typeBox.addEventListener("click",function(e){
  focusCapture(); typeBox.classList.add("focused");
  if(state.finished) return;
  var span=(e.target&&e.target.classList&&e.target.classList.contains("ch"))? e.target : null;
  if(span){
    var idx=Array.prototype.indexOf.call(typeText.children,span);
    if(idx>=0){
      var r=span.getBoundingClientRect();
      setHcmCaret(idx + ((e.clientX > r.left + r.width/2)? 1:0));
    }
  } else {
    setHcmCaret(state.typed.length);
  }
});
typeBox.addEventListener("keydown",function(e){

  if(e.target===capture) return;

  if(e.key==="PageDown"||e.key==="PageUp"){ e.preventDefault(); focusCapture(); return; }
  if(e.key==="Backspace"){
    e.preventDefault(); focusCapture();
    if(state.finished) return;
    if(capture.value.length){
      state.bsCount++;
      capture.value=capture.value.slice(0,-1);
      capture.dispatchEvent(new Event("input",{bubbles:true}));
    }
    return;
  }
  if(e.key && e.key.length===1){
    e.preventDefault(); focusCapture();
    if(!state.finished){
      capture.value+=e.key;
      capture.dispatchEvent(new Event("input",{bubbles:true}));
    }
    return;
  }
  if(document.activeElement!==capture) focusCapture();
});
capture.addEventListener("blur",function(){ typeBox.classList.remove("focused"); });

function computeMistakes(){
  var al=alignWordsHcm(state.target||"", typedString());
  var map={}, order=[];
  al.pairs.forEach(function(p){
    if(p.kind==="ok") return;
    var exp, got;
    if(p.kind==="sub"){ exp=p.exp; got=p.got; }
    else if(p.kind==="spacing"){ exp=p.exp; got=p.got; }
    else if(p.kind==="del"){ exp=p.exp; got="(missed)"; }
    else { exp="(extra)"; got=p.got; }
    var key=exp+"\u0001"+got;
    if(!map[key]){ map[key]={exp:exp,got:got,count:0}; order.push(map[key]); }
    map[key].count++;
  });
  order.sort(function(a,b){ return b.count-a.count; });
  var uniq=[]; order.forEach(function(r){ if(r.exp!=="(extra)"&&uniq.indexOf(r.exp)<0) uniq.push(r.exp); });
  return {rows:order.slice(0,40), total:al.mistakes, unique:uniq};
}

function deriveErrCats(){
  var al=alignWordsHcm(state.target||"", typedString());
  var cat={spelling:0,capital:0,punct:0,spacing:0,other:0}, keys={}, words={};
  al.pairs.forEach(function(p){
    if(p.kind==="ok") return;
    if(p.kind==="spacing"){ cat.spacing++; keys[" "]=(keys[" "]||0)+1; p.exp.split(" ").forEach(function(w){ if(w) words[w]=(words[w]||0)+1; }); return; }
    if(p.kind==="del"){ cat.other++; words[p.exp]=(words[p.exp]||0)+1; return; }
    if(p.kind==="ins"){ cat.other++; return; }
    var e=p.exp, g=p.got;
    if(e.length!==g.length&&(e.indexOf(g)===0||g.indexOf(e)===0)){

      cat.spacing++; keys[" "]=(keys[" "]||0)+1;
    } else {
      var lim=Math.max(e.length,g.length), counted=false;
      for(var i2=0;i2<lim;i2++){
        var ec=i2<e.length?e[i2]:"", gc=i2<g.length?g[i2]:"";
        if(ec===gc) continue;
        if(!counted){ cat[classify(ec||" ",gc||" ")]++; counted=true; }
        var kk=ec||gc; keys[kk]=(keys[kk]||0)+1;
      }
    }
    words[e]=(words[e]||0)+1;
  });
  state.errCat=cat; state.errKeys=keys; state.errWords=words;
}
function bandLabel(n){
  if(n<30) return "below 30 net WPM — disqualified (0 marks)";
  if(n<31) return "30 net WPM band — 10 marks";
  if(n<=35) return "31–35 band — 12 marks";
  if(n<=40) return "36–40 band — 15 marks";
  if(n<=45) return "41–45 band — 18 marks";
  if(n<=50) return "46–50 band — 21 marks";
  return "51+ band — full 25 marks";
}
