(function migrateName(){
  if(typeof SETTINGS.name==="string"){ if(SETTINGS.name.trim()===LEGACY_PLACEHOLDER_NAME){ SETTINGS.name=""; persistSettings(); } return; }
  var v="";
  if(typeof SETTINGS.siteName==="string" && SETTINGS.siteName.trim() && SETTINGS.siteName.trim()!==LEGACY_PLACEHOLDER_NAME) v=SETTINGS.siteName.trim();
  else{ try{ var d=localStorage.getItem(LS_NAME); if(d && d.trim() && d.trim()!==LEGACY_PLACEHOLDER_NAME) v=d.trim(); }catch(e){} }
  SETTINGS.name=v;
  if("siteName" in SETTINGS) delete SETTINGS.siteName;
  persistSettings();
})();
