var ACCTNAME_CACHE_PREFIX="hcm_acctname_v1:";
function acctNameCacheGet(uid){
  try{ if(!uid) return ""; return (localStorage.getItem(ACCTNAME_CACHE_PREFIX+uid)||"").trim(); }catch(e){ return ""; }
}
function acctNameCacheSet(uid,name){
  try{
    if(!uid) return;
    var n=(name||"").trim();
    if(n) localStorage.setItem(ACCTNAME_CACHE_PREFIX+uid,n);
    else localStorage.removeItem(ACCTNAME_CACHE_PREFIX+uid);
  }catch(e){}
}
function accountNameFromProfileData(dd){
  if(typeof dd.name==="string" && dd.name.trim() && dd.name.trim()!==LEGACY_PLACEHOLDER_NAME) return dd.name.trim();
  if(typeof dd.siteName==="string" && dd.siteName.trim() && dd.siteName.trim()!==LEGACY_PLACEHOLDER_NAME) return dd.siteName.trim();
  if(typeof dd.displayName==="string" && dd.displayName.trim() && dd.displayName.trim()!==LEGACY_PLACEHOLDER_NAME) return dd.displayName.trim();
  return null;
}

function fetchAccountName(){
  if(!window.__fbUser||typeof fbDb==="undefined"||!fbDb) return;
  var uid=window.__fbUser.uid;
  fbDb.collection("users").doc(uid).get().then(function(doc){
    var cn=accountNameFromProfileData(doc.data()||{});
    if(cn!==null){ window.__accountName=cn; acctNameCacheSet(uid,cn); applySiteName(); applyName(); }
  }).catch(function(){});
}
