  var av=document.getElementById("profAvatar");
  if(av){ var src=n||(user&&user.email)||""; if(src) av.textContent=src.charAt(0).toUpperCase(); else av.innerHTML=USER_ICON_SVG; }
  var pn=document.getElementById("profName"); if(pn) pn.textContent= n || (user? (user.email||"Your account") : "Not signed in");
  var ps=document.getElementById("profSub");
  if(ps) ps.textContent= user? (user.email||"Signed in") : "Sign in to sync progress across devices";

  var eb=document.getElementById("editNameBtn"); if(eb) eb.style.display= user? "" : "none";
