function saveNameToCloud(){
  try{
    if(typeof fbDb==="undefined"||!fbDb||!window.__fbUser) return;
    var n=(SETTINGS.name||"");
    window.__accountName=n.trim();
    acctNameCacheSet(window.__fbUser.uid,n);
    var uid=window.__fbUser.uid;
    RateLimit.debounce("nameSave",1500,function(){
      fbDb.collection("users").doc(uid).set({name:n,siteName:n,displayName:n},{merge:true}).catch(function(e){ console.warn("Name cloud save failed",e); });
    });
  }catch(e){ console.warn("Name cloud save failed",e); }
}
