function openLearn(kind){
  var title=document.getElementById("learnTitle"), body=document.getElementById("learnBody"), ov=document.getElementById("learnOverlay");
  if(!title||!body||!ov) return;
  if(kind==="guide"){
    title.textContent="Exam Guide & Method";
    var gp=document.getElementById("panel-guide"); body.innerHTML= gp? gp.innerHTML : "";
  } else {
    title.textContent="30-Day Plan & Checklist";
    var pc=document.getElementById("planCard"), cc=document.getElementById("checklistCard");
    body.innerHTML= (pc? pc.outerHTML : "")+(cc? cc.outerHTML : "");
  }
  body.querySelectorAll("[id]").forEach(function(el){ el.removeAttribute("id"); });
  applyName();
  closeDrawer();
  ov.classList.add("open"); ov.setAttribute("aria-hidden","false");
  ov.scrollTop=0;
}
function closeLearn(){
  var ov=document.getElementById("learnOverlay");
  if(ov){ ov.classList.remove("open"); ov.setAttribute("aria-hidden","true"); }
}
var learnGuideEl=document.getElementById("learnGuide");
if(learnGuideEl) learnGuideEl.addEventListener("click",function(){ openLearn("guide"); });
