if(learnPlanEl) learnPlanEl.addEventListener("click",function(){ openLearn("plan"); });
var learnCloseEl=document.getElementById("learnClose");
if(learnCloseEl) learnCloseEl.addEventListener("click",closeLearn);
var learnOverlayEl=document.getElementById("learnOverlay");
if(learnOverlayEl) learnOverlayEl.addEventListener("click",function(e){ if(e.target===learnOverlayEl) closeLearn(); });

function downloadFile(name, content, type){
  var b=new Blob([content],{type:type}); var u=URL.createObjectURL(b);
  var a=document.createElement("a"); a.href=u; a.download=name; document.body.appendChild(a); a.click();
  setTimeout(function(){ URL.revokeObjectURL(u); a.remove(); },400);
}
