document.getElementById("importBtn").addEventListener("click",function(){ document.getElementById("importFile").click(); });
document.getElementById("importFile").addEventListener("change",function(e){
  var f=e.target.files[0]; if(!f) return;
  var r=new FileReader();
  r.onload=function(){
    try{
      var d=JSON.parse(r.result);
      if(!d || !Array.isArray(d.history)) throw new Error("bad file");
      saveHist(d.history);
      if(d.drillsDone) saveDone(d.drillsDone);
      if(d.lessonBest && typeof d.lessonBest==="object" && !Array.isArray(d.lessonBest)){

        var nb={}; Object.keys(d.lessonBest).forEach(function(k){ var a=Array.isArray(d.lessonBest[k])?d.lessonBest[k]:[]; nb[k]=sortBestArr(a).slice(0,10); });
        saveBest(nb);
      }
      if(d.profileName && String(d.profileName).trim() && String(d.profileName).trim()!==LEGACY_PLACEHOLDER_NAME){ SETTINGS.name=String(d.profileName).trim(); persistSettings(); }
      if(d.settings && typeof d.settings==="object" && !Array.isArray(d.settings)){
        if(typeof d.settings.autoSubmit==="boolean") SETTINGS.autoSubmit=d.settings.autoSubmit;
        if(typeof d.settings.highlight==="boolean"||d.settings.highlight===null) SETTINGS.highlight=d.settings.highlight;
        if(typeof d.settings.name==="string") SETTINGS.name= d.settings.name.trim()===LEGACY_PLACEHOLDER_NAME? "" : d.settings.name.trim();
        else if(typeof d.settings.siteName==="string") SETTINGS.name= d.settings.siteName.trim()===LEGACY_PLACEHOLDER_NAME? "" : d.settings.siteName.trim();
        persistSettings(); applySiteName(); paintFinishUI(); applyHighlightUI(); renderText(); saveNameToCloud();
      }
      applyName(); renderDashboard(); renderHistory(); renderDrills(); renderWarmups(); updateLessonHistory(); renderTrends();
      document.getElementById("backupMsg").textContent="✅ Backup restored: "+d.history.length+" test(s) imported on this device.";
    }catch(err){
      document.getElementById("backupMsg").textContent="⚠ That file could not be read as an HCM typing backup. Please choose the JSON backup downloaded from this site.";
    }
    e.target.value="";
  };
  r.readAsText(f);
});

var trendRange="all";
document.querySelectorAll(".trendRange").forEach(function(b){ b.addEventListener("click",function(){ document.querySelectorAll(".trendRange").forEach(function(x){x.classList.remove("active")}); b.classList.add("active"); trendRange=b.dataset.range; renderTrends(); }); });
function filteredHist(){
  var h=loadHist().slice().sort(function(a,b){ return new Date(a.ts||a.d)-new Date(b.ts||b.d); });
  if(trendRange==="all") return h;
  var days=+trendRange, cut=Date.now()-days*86400000;
  return h.filter(function(x){ var t=new Date(x.ts||x.d).getTime(); return !isNaN(t) && t>=cut; });
}
function lineChartSVG(vals,color,unit,targetY,maxY){
  if(!vals.length) return "<p class='small'>No data yet.</p>";
  var W=640,H=180,pad=36, min=0;
  var dataMax=Math.max.apply(null,vals.concat([targetY||0]));

  var dynamicMax=dataMax>0 ? dataMax*1.2+4 : 10;
  var max=Math.max(dynamicMax, maxY||0);
  if(color==="#178a4c" && dataMax<=100){ max=Math.min(max,100); if(max<dataMax) max=dataMax; min=Math.max(0,Math.min.apply(null,vals)-5); if(min>=max) min=0; }
  var pts=vals.map(function(v,i){ var x=vals.length===1? W/2 : pad+i*(W-2*pad)/(vals.length-1); var y=H-pad-((v-min)/(max-min))*(H-2*pad); return x.toFixed(1)+","+y.toFixed(1); }).join(" ");
  var targetLine="";
  if(targetY!=null){ var ty=H-pad-((targetY-min)/(max-min))*(H-2*pad); targetLine="<line x1='"+pad+"' y1='"+ty+"' x2='"+(W-pad)+"' y2='"+ty+"' stroke='#c62828' stroke-width='1.5' stroke-dasharray='6 4'/><text x='"+(W-pad)+"' y='"+(ty-6)+"' text-anchor='end' font-size='11' fill='#c62828'>goal "+targetY+"</text>"; }
  return "<svg viewBox='0 0 "+W+" "+H+"' width='100%' role='img' style='max-width:100%;height:auto'><line x1='"+pad+"' y1='"+(H-pad)+"' x2='"+(W-pad)+"' y2='"+(H-pad)+"' stroke='#888'/><text x='4' y='20' font-size='11' fill='currentColor'>"+unit+"</text><text x='4' y='"+(H-pad)+"' font-size='11' fill='currentColor'>"+Math.round(min)+"</text><text x='4' y='36' font-size='11' fill='currentColor'>"+Math.round(max)+"</text>"+targetLine+"<polyline fill='none' stroke='"+color+"' stroke-width='2.5' points='"+pts+"'/></svg>";
}
function barsSVG(vals){
  if(!vals.length) return "<p class='small'>No data yet.</p>";
  var dataMaxB=Math.max.apply(null,vals.concat([25]));
  var W=640,H=180,pad=36,max=Math.max(25,dataMaxB*1.15),bw=Math.max(6,(W-2*pad)/vals.length-4);
  var rects=vals.map(function(v,i){ var h=(v/max)*(H-2*pad); var x=pad+i*((W-2*pad)/vals.length); return "<rect x='"+x+"' y='"+(H-pad-h)+"' width='"+bw+"' height='"+h+"' fill='#1d6fd1'><title>"+v+" / 25</title></rect>"; }).join("");
  var ty=H-pad-(25/max)*(H-2*pad);
  return "<svg viewBox='0 0 "+W+" "+H+"' width='100%' role='img' style='max-width:100%;height:auto'><line x1='"+pad+"' y1='"+(H-pad)+"' x2='"+(W-pad)+"' y2='"+(H-pad)+"' stroke='#888'/>"+rects+"<text x='4' y='20' font-size='11' fill='currentColor'>marks</text></svg>";
}
function renderTrends(){
  var empty=document.getElementById("trendEmpty"), body=document.getElementById("trendBody");
  if(!empty||!body) return;
  var h=filteredHist(), all=loadHist();
  if(!all.length){ empty.style.display="block"; body.style.display="none"; return; }
  empty.style.display="none"; body.style.display="block";
  var data=h.length?h:all;
  var total=data.length;
  var mins=data.reduce(function(a,x){return a+(x.durSec?x.durSec/60:(x.min||0))},0);
  document.getElementById("tTotal").textContent=total;
  document.getElementById("tTime").textContent= mins>=60? (mins/60).toFixed(1)+"h" : Math.round(mins)+"m";
  document.getElementById("tBest").textContent=Math.max.apply(null,data.map(function(x){return x.net}))+" WPM";
  var avgNet=data.reduce(function(a,x){return a+x.net},0)/total;
  document.getElementById("tAvgNet").textContent=avgNet.toFixed(1);
  var last10=data.slice(-10); document.getElementById("tAvg10").textContent=(last10.reduce(function(a,x){return a+x.net},0)/last10.length).toFixed(1);
  document.getElementById("tAcc").textContent=(data.reduce(function(a,x){return a+x.acc},0)/total).toFixed(1)+"%";
  var weekCut=Date.now()-7*86400000; document.getElementById("tWeek").textContent=all.filter(function(x){return new Date(x.ts||x.d).getTime()>=weekCut}).length;
  var daysSet={}; all.forEach(function(x){ var d=new Date(x.ts||x.d); if(!isNaN(d)) daysSet[d.toDateString()]=1; });
  var streak=0, cur=new Date(); while(daysSet[cur.toDateString()]){ streak++; cur.setDate(cur.getDate()-1); }
  document.getElementById("tStreak").textContent=streak+(streak===1?" day":" days");
  var best=Math.max.apply(null,all.map(function(x){return x.net}));
  document.getElementById("tGoal").innerHTML= best>50? "🏆 <strong>Goal reached:</strong> best net "+best+" WPM is above 50 — full 25-mark band. Now make it repeatable in 10-minute tests." : "🎯 <strong>Progress to full marks:</strong> best net "+best+" WPM — "+(51-best)+" WPM short of the 51+ band for 25/25. Average net is "+avgNet.toFixed(1)+" WPM.";
  document.getElementById("chartNet").innerHTML=lineChartSVG(data.map(function(x){return x.net}),"#1d6fd1","net WPM",50,60);
  document.getElementById("chartAcc").innerHTML=lineChartSVG(data.map(function(x){return x.acc}),"#178a4c","accuracy %",98,100);
  document.getElementById("chartMarks").innerHTML=barsSVG(data.map(function(x){return x.marks||0}));
  var catTotals={spelling:0,capital:0,punct:0,spacing:0,other:0};
  data.forEach(function(x){ if(x.errCat) Object.keys(catTotals).forEach(function(k){ catTotals[k]+=x.errCat[k]||0; }); else catTotals.spelling+=x.errs||0; });
  var maxCat=Math.max(1,Math.max.apply(null,Object.values(catTotals)));
  var catNames={spelling:"Spelling / wrong character",capital:"Capitalisation",punct:"Punctuation",spacing:"Spacing",other:"Other"};
  document.getElementById("chartErrors").innerHTML=Object.keys(catTotals).map(function(k){ var pct=Math.round(catTotals[k]/maxCat*100); return "<div style='margin-bottom:8px'><div style='display:flex;justify-content:space-between;font-size:13px'><span>"+catNames[k]+"</span><strong>"+catTotals[k]+"</strong></div><div class='progress' style='margin:4px 0'><i style='width:"+pct+"%;background:var(--red)'></i></div></div>"; }).join("");
  var keyAgg={}, wordAgg={};
  data.forEach(function(x){ if(x.weakKeys) Object.keys(x.weakKeys).forEach(function(k){keyAgg[k]=(keyAgg[k]||0)+x.weakKeys[k]}); if(x.weakWords) Object.keys(x.weakWords).forEach(function(k){wordAgg[k]=(wordAgg[k]||0)+x.weakWords[k]}); });
  var topKeys=Object.keys(keyAgg).sort(function(a,b){return keyAgg[b]-keyAgg[a]}).slice(0,8).map(function(k){return "'"+(k===" "?"space":k)+"' ×"+keyAgg[k]}).join(", ");
  var topWords=Object.keys(wordAgg).sort(function(a,b){return wordAgg[b]-wordAgg[a]}).slice(0,8).map(function(k){return k+" ×"+wordAgg[k]}).join(", ");
  document.getElementById("tWeak").innerHTML=(topKeys?("Weakest keys: <strong>"+topKeys+"</strong><br>"):"No key data yet — older results did not record keys.<br>")+(topWords?("Words with most errors: <strong>"+topWords+"</strong>"):"");
  var insight="";
  if(data.length>=4){ var half=Math.floor(data.length/2); var first=data.slice(0,half), second=data.slice(half); var fAvg=first.reduce(function(a,x){return a+x.net},0)/first.length, sAvg=second.reduce(function(a,x){return a+x.net},0)/second.length; insight="Net speed moved from "+fAvg.toFixed(1)+" WPM (first "+first.length+" tests in this view) to "+sAvg.toFixed(1)+" WPM (last "+second.length+"). "; }
  else insight="Keep going — insights get sharper after a few tests. ";
  var biggest=Object.keys(catTotals).sort(function(a,b){return catTotals[b]-catTotals[a]})[0];
  var drillMap={spacing:"Part 5 → Spacing Traps",punct:"Part 5 → Punctuation, Numbers, Dates",capital:"Part 2 → Opposite-Hand Shift drill",spelling:"Part 1 row drills + Part 3 n-gram chunks",other:"Part 6 sentences at the 98% gate"};
  if(catTotals[biggest]>0) insight+="Your biggest leak is "+catNames[biggest].toLowerCase()+" errors ("+catTotals[biggest]+") — do "+(drillMap[biggest]||"Part 1 drills")+" next.";
  else insight+="No errors recorded in this view — excellent. Build speed with Part 3 chunks and longer tests.";
  document.getElementById("tInsight").textContent=insight;
}

