function authMsg(t,isErr){ var el=document.getElementById("authMsg"); if(el){ el.textContent=t||""; el.style.color=isErr?"var(--red)":"var(--green)"; } }
function friendlyAuthError(e){
  var c=e&&e.code?e.code:"";
  if(c==="auth/wrong-password") return "Wrong password — please try again, or use Forgot password.";
  if(c==="auth/user-not-found") return "No account found for that email — tap Create account first.";
  if(c==="auth/email-already-in-use") return "That email already has an account — tap Log in instead.";
  if(c==="auth/weak-password") return "Password is too weak — use at least 6 characters.";
  if(c==="auth/invalid-email") return "That email address does not look valid — please check it.";
  if(c==="auth/invalid-credential") return "Email or password is incorrect — please try again.";
  if(c==="auth/too-many-requests") return "Too many attempts — please wait a few minutes and try again.";
  if(c==="auth/network-request-failed") return "No connection — check your internet and try again.";
  if(c==="auth/missing-password") return "Enter your password.";
  return "Something went wrong — please try again.";
}
function entryToCloud(x){
  return {clientId:x.clientId,clientTime:x.ts||new Date().toISOString(),date:x.d,title:x.name,part:x.part||x.name,durationSec:x.durSec||((x.min||0)*60),durationMin:x.min||0,grossWPM:x.gross,netWPM:x.net,accuracy:x.acc,totalErrors:x.errs,errorBreakdown:x.errCat||{spelling:x.errs||0,capital:0,punct:0,spacing:0,other:0},marks:x.marks||0,characters:x.chars||0,words:x.words||0,telemetry:x.telemetry||null,weakestKeys:x.weakKeys||{},weakestWords:x.weakWords||{},examId:x.examId||'',testId:x.testId||'',category:x.category||'',engine:x.engine||'',fullMistakes:(x.full!=null?x.full:0),halfMistakes:(x.half!=null?x.half:0),errorPct:(x.errorPct!=null?x.errorPct:null),verdict:x.verdict||'',mistakeDetail:x.mistakeDetail||null,timestamp:(window.firebase&&firebase.firestore&&firebase.firestore.FieldValue)?firebase.firestore.FieldValue.serverTimestamp():null};
}
function cloudToEntry(doc){
  var v=doc.data();
  var en={clientId:v.clientId||doc.id,ts:v.clientTime||new Date().toISOString(),d:v.date||new Date(v.clientTime||Date.now()).toLocaleString("en-IN"),name:v.title||"Test",part:v.part||v.title||"",gross:v.grossWPM||0,net:v.netWPM||0,acc:v.accuracy||0,errs:v.totalErrors||0,marks:v.marks||0,min:(v.durationMin||Math.round((v.durationSec||0)/60)||5),durSec:v.durationSec||0,chars:v.characters||0,words:v.words||0,errCat:v.errorBreakdown||{},weakKeys:v.weakestKeys||{},weakWords:v.weakestWords||{},examId:v.examId||'',testId:v.testId||'',category:v.category||'',engine:v.engine||'',full:(v.fullMistakes||0),half:(v.halfMistakes||0),errorPct:(v.errorPct!=null?v.errorPct:null),verdict:v.verdict||'',synced:true};
  if(v.telemetry) en.telemetry=v.telemetry;
  if(v.mistakeDetail) en.mistakeDetail=v.mistakeDetail;
  return en;
}
function saveResultToCloud(entry,isBackfill){
  if(!fbDb||!window.__fbUser) return Promise.resolve(false);
  if(!isBackfill && rateLimited("cloudWrite")){ window.__cloudLimited=true; return Promise.resolve(false); }
  window.__cloudLimited=false;
  var uid=window.__fbUser.uid;
  return fbDb.collection("users").doc(uid).collection("results").doc(entry.clientId).set(entryToCloud(entry),{merge:true}).then(function(){
    var h=loadHist(); h.forEach(function(x){ if(x.clientId===entry.clientId) x.synced=true; }); saveHist(h);
    var ss=document.getElementById("syncState"); if(ss) ss.textContent="Last result saved to cloud ✓";
    return true;
  }).catch(function(e){ console.warn("Cloud save failed",e); return false; });
}
var mergeCloudBusyFor=null;
function mergeCloud(){
  if(!fbDb||!window.__fbUser) return;
  if(mergeCloudBusyFor===window.__fbUser.uid) return;
  mergeCloudBusyFor=window.__fbUser.uid;
  var uid=window.__fbUser.uid, ss=document.getElementById("syncState"); if(ss) ss.textContent="Syncing…";
  fbDb.collection("users").doc(uid).collection("results").get().then(function(snap){
    var cloud=[]; snap.forEach(function(doc){ cloud.push(cloudToEntry(doc)); });
    var local=loadHist(); var byId={}; cloud.forEach(function(x){byId[x.clientId]=x});
    var toUpload=[];
    local.forEach(function(x){ if(byId[x.clientId]){ x.synced=true; } else { toUpload.push(x); } });
    var combined=cloud.concat(toUpload.map(function(x){ var y=Object.assign({},x); y.synced=false; return y; }));
    combined.sort(function(a,b){ return new Date(b.ts)-new Date(a.ts); });
    saveHist(combined);
    var uploads=toUpload.slice(0,200).map(function(x){ return saveResultToCloud(x,true); });
    return Promise.all(uploads);
  }).then(function(){ renderDashboard(); renderHistory(); renderTrends(); if(ss) ss.textContent="Cloud synced ✓"; mergeCloudBusyFor=null; }).catch(function(e){ console.warn("Sync failed",e); mergeCloudBusyFor=null; if(ss) ss.textContent="Cloud sync failed — showing device results"; });
}
function initFirebase(){
  if(typeof firebase==="undefined"){ if(typeof authGateUpdate==="function") authGateUpdate(null); authMsg("Cloud login is unavailable right now — you can still practise fully; results save on this device only.",true); return; }
  try{
    if(!firebase.apps.length) firebase.initializeApp(firebaseConfig);
    fbAuth=firebase.auth(); fbDb=firebase.firestore();
    fbAuth.setPersistence(firebase.auth.Auth.Persistence.LOCAL).catch(function(){});
    fbAuth.onAuthStateChanged(function(user){
      window.__fbUser=user||null;
      if(typeof authGateUpdate==="function") authGateUpdate(user||null);
      if(user){
        var dn=(user.displayName||"").trim();
        window.__accountName= dn || acctNameCacheGet(user.uid) || "";
        if(dn) acctNameCacheSet(user.uid,dn);
      } else { window.__accountName=""; }
      try{ applyName(); }catch(e){ try{ paintProfile(); }catch(e2){} }
      var out=document.getElementById("authLoggedOut"), inn=document.getElementById("authLoggedIn"), st=document.getElementById("authStatus");
      if(user){
        if(out) out.style.display="none"; if(inn) inn.style.display="block";
        document.getElementById("authUserEmail").textContent=user.email||"";
        if(st){ st.textContent="Logged in — results save to your account"; st.className="syncOk"; }
        authMsg("");
        fbDb.collection("users").doc(user.uid).set({email:user.email||"",lastLogin:firebase.firestore.FieldValue.serverTimestamp()},{merge:true}).catch(function(){});
        fetchAccountName();
        mergeCloud();
        if(typeof revCloudSync==="function"){ try{ revCloudSync(); }catch(e){ console.warn("Revision sync failed",e); } }
        try{ if(typeof mergeBestFromCloud==="function") mergeBestFromCloud().then(function(){ try{renderDrills();renderWarmups();updateLessonHistory();}catch(e){} }); }catch(e){ console.warn("Cloud best merge failed",e); }
      } else {
        if(out) out.style.display="block"; if(inn) inn.style.display="none";
        if(st){ st.textContent="Not logged in — results save only on this device"; st.className="syncOff"; }
        try{ applyName(); applySiteName(); }catch(e){}
        renderTrends();
      }
    });
  }catch(e){ console.warn("Firebase init failed",e); authMsg("Cloud login is unavailable right now — you can still practise fully; results save on this device only.",true); }
  var ob=document.getElementById("logoutBtn");
  if(ob) ob.addEventListener("click",function(){ if(fbAuth) fbAuth.signOut(); });
}

